const {HeadImageLayoutControl}=layoutModule.exports;
const layoutValues={Axial:'axial',Coronal:'coronal',Sagittal:'sagittal',Multiplanar:'multiplanar','3D scan view':'3d'} as const;

function layoutSelect(root:unknown=tree){
  const control=walk(root,node=>node.type===HeadImageLayoutControl);assert(control,'rendered image layout control');
  const select=walk(HeadImageLayoutControl({layout:control.props.layout,practice:control.props.practice,onChange:control.props.onChange}),node=>node.type==='select'&&node.props['aria-label']==='Image layout');
  assert(select,'real image layout select');return select;
}
function layoutOption(label:keyof typeof layoutValues,root:unknown=tree){
  const value=layoutValues[label];
  const option=walk(layoutSelect(root),node=>node.type==='option'&&node.props.value===value);
  assert(option,`rendered ${label} option`);assert.equal(content(option.props.children),label);
  return option;
}
function chooseLayout(label:keyof typeof layoutValues){
  const option=layoutOption(label);assert.equal(option.props.disabled,false,`enabled ${label}`);
  layoutSelect().props.onChange({currentTarget:{value:option.props.value}});return flush();
}
function act(text:string){if(Object.hasOwn(layoutValues,text))return chooseLayout(text as keyof typeof layoutValues);const button=find('button',text);assert(button,`rendered button ${text}`);assert.notEqual(button.props.disabled,true,`enabled ${text}`);button.props.onClick();return flush();}
// Tests that deliberately defer image reads must be able to resolve that read
// themselves. Await its start here, not the still-pending image completion.
async function choosePackage(name:string){
  const input=walk(tree,node=>node.type==='input'&&node.props.type==='file');assert(input);
  const before=studyRequests.length;
  const opening=input.props.onChange({target:{files:[{name}],value:name}}) as Promise<void>;
  if(!options.deferStudy||options.deferPackage)return opening;
  let completed=false,failure:unknown;const observed=opening.then(()=>{completed=true;},error=>{failure=error;completed=true;});
  for(let turn=0;turn<12&&studyRequests.length===before&&!completed;turn++)await settle();
  if(failure)throw failure;
  assert(studyRequests.length>before||completed,'manual open reaches its deferred study or completes');
  // Keep rejection observed while the test owns the deferred response.
  void observed;
}

